<div class="top"><div><h2 style="margin:0">Recurring tasks</h2><span class="muted"><a href="/staff/tasks">&larr; Tasks</a> &middot; A new task is created automatically on each date.</span></div></div>
<div class="card mb"><div class="tw"><table><tr><th>Task</th><th>Repeats</th><th>Next</th><th>Assigned to</th><th></th></tr>
<?php foreach ($rows as $r): ?><tr><td><?= e($r['title']) ?><?= $r['active'] ? '' : ' ' . badge('Paused') ?></td><td><?= e(rec_text($r)) ?></td><td><?= e(fmt_date($r['next_run'])) ?></td><td><?= e((string) ($r['aname'] ?? 'unassigned')) ?></td>
<td style="white-space:nowrap"><form method="post" action="/staff/recurring/<?= (int) $r['id'] ?>" class="inline"><?= csrf_field() ?><button class="btn sm alt" name="action" value="toggle"><?= $r['active'] ? 'Pause' : 'Resume' ?></button> <button class="btn sm danger" name="action" value="delete" data-confirm="Remove this schedule? Tasks already created stay.">Remove</button></form></td></tr>
<?php endforeach; if (!$rows): ?><tr><td colspan="5" class="muted">No recurring tasks yet.</td></tr><?php endif; ?></table></div></div>
<div class="card" style="max-width:760px"><h3>New recurring task</h3><form method="post" action="/staff/recurring"><?= csrf_field() ?>
<label for="rt">Title</label><input id="rt" name="title" required maxlength="160" placeholder="e.g. Weekly stock check">
<label for="rd">Description (checklist lines with - [ ] work)</label><textarea id="rd" name="description" rows="3" maxlength="4000"></textarea>
<div class="row"><div><label for="rf">Repeat</label><select id="rf" name="freq"><?= options(REC_FREQ, 'weekly') ?></select></div><div><label for="re">Every (number)</label><input id="re" name="every" inputmode="numeric" value="1"></div><div><label for="rs">First date</label><input id="rs" type="date" name="start" required value="<?= e(date('Y-m-d')) ?>"></div></div>
<p class="muted" style="margin-top:-6px">Weekly repeats on the weekday of the first date; monthly on its day of the month.</p>
<div class="row"><div><label for="ra">Assign to</label><select id="ra" name="assignee_id"><option value="">Unassigned</option><?php foreach ($people as $p): ?><option value="<?= (int) $p['id'] ?>"><?= e($p['name']) ?></option><?php endforeach; ?></select></div><div><label for="rp">Priority</label><select id="rp" name="priority"><?= options(TASK_PRIORITIES, 'normal') ?></select></div><div><label for="rdd">Due after (days)</label><input id="rdd" name="due_days" inputmode="numeric" value="0"></div></div>
<label for="rg">Group (optional)</label><input id="rg" name="phase" maxlength="40" placeholder="Recurring"><button class="btn">Save schedule</button></form></div>
